mapper.select:
SELECT  COUNT(checkin) AS work_day,
ROUND(
    COALESCE(
        SUM(TIME_TO_SEC(TIMEDIFF(checkout, checkin)) / 3600),
        0
    ),
    1
) AS total_work_time,
ROUND(
    COALESCE(
        SUM(
            GREATEST( 
                TIME_TO_SEC(TIMEDIFF(checkout, checkin)) / 3600 - 9,
                0
            )
        ),
        0
    ),
    1
) AS overtime
FROM ta
WHERE sabun = #{sabun}
AND checkin IS NOT NULL
AND checkout IS NOT NULL
AND YEAR(day) = YEAR(NOW())
AND MONTH(day) = MONTH(NOW());

WITH RECURSIVE calendar AS ( SELECT GREATEST( DATE(CONCAT(#{year}, '-01-01')), (SELECT DATE(sahire) FROM sawon WHERE sabun = #{sabun}) -- 입사일과 비교 ) AS day UNION ALL SELECT DATE_ADD(day, INTERVAL 1 DAY) FROM calendar WHERE day < LEAST( DATE(CONCAT(#{year}, '-12-31')), CURDATE() -- 오늘 날짜와 비교해서 더 작은 값까지만 ) ) SELECT #{sabun} AS sabun, DATE_FORMAT(c.day, '%Y-%m-%d') AS day, TIME_FORMAT(t.checkin, '%H:%i') as checkin, TIME_FORMAT(t.checkout,'%H:%i') as checkout, TIME_FORMAT(timediff(t.checkout, t.checkin), '%H시 %i분') as working_time, CASE WHEN sl.use_date IS NOT NULL AND sl.use_days = 0.5 THEN 'half' WHEN sl.use_date IS NOT NULL AND sl.use_days = 1 THEN 'leave' WHEN t.checkin IS NULL THEN 'absent' -- 행 없으면 NULL WHEN TIME(t.checkin) > '09:00:00' THEN 'late' ELSE 'normal' END AS status FROM calendar c LEFT JOIN ta t ON t.sabun = #{sabun}
AND DATE(t.day) = c.day LEFT JOIN sleave_log sl ON sl.sabun = #{sabun} AND c.day = sl.use_date AND sl.approve = true WHERE DAYOFWEEK(c.day) NOT IN (1, 7)
AND MONTH(c.day) = #{month}
AND 1 = 1
ORDER BY c.day ASC
ORDER BY c.day DESC
